/* Locally authored Blender models, persistent vehicles and conservative substep movement. */
(()=>{'use strict';const T=THREE,W=EmberTerrain,D=SurvivalData,P=EmberWorld.prototype,assets=new Map(),models=new Map(),registry=new Map();
const config={car:{name:'探索用四輪駆動車',radius:3,width:1.12,length:2.6,max:26,burn:.12},airplane:{name:'小型プロペラ機',radius:5.6,width:5.1,length:3.5,max:52,burn:.3}};
function ready(kind){if(assets.has(kind))return assets.get(kind);const promise=fetch('assets/survival/vehicles/'+kind+'.json').then(r=>{if(!r.ok)throw Error('車体モデルを読み込めません');return r.json();}).then(data=>{const materials={};for(const[name,m]of Object.entries(data.materials)){const mat=new T.MeshStandardMaterial({color:new T.Color(m.color).convertSRGBToLinear(),roughness:m.roughness,metalness:m.metalness,transparent:m.opacity<1,opacity:m.opacity,side:m.opacity<1?T.DoubleSide:T.FrontSide,depthWrite:m.opacity>=1});if(m.texture){mat.map=new T.TextureLoader().load('assets/survival/vehicles/'+m.texture);mat.map.encoding=T.sRGBEncoding;mat.map.wrapS=mat.map.wrapT=T.RepeatWrapping;mat.color.setHex(0xffffff);}if(m.emission){mat.emissive.copy(mat.color);mat.emissiveIntensity=m.emission;}materials[name]=mat;}const template=new T.Group(),parts={};for(const g of data.groups){let part=parts[g.part];if(!part){part=new T.Group();part.name=g.part;part.position.fromArray(g.origin);parts[g.part]=part;template.add(part);}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(g.positions,3));geometry.setAttribute('normal',new T.Float32BufferAttribute(g.normals,3));geometry.setAttribute('uv',new T.Float32BufferAttribute(g.uv,2));geometry.computeBoundingSphere();const mesh=new T.Mesh(geometry,materials[g.material]);mesh.castShadow=g.material!=='glass';mesh.receiveShadow=true;part.add(mesh);}models.set(kind,template);return template;});assets.set(kind,promise);return promise;}
function sync(world,state){state.vehicles||=[];for(const[id,g]of registry)if(!state.vehicles.some(v=>v.id===id&&v.kind===g.userData.kind)){world.dynamic.remove(g);registry.delete(id);}for(const v of state.vehicles)if(!registry.has(v.id)){const g=new T.Group();g.userData.vehicleId=v.id;g.userData.kind=v.kind;world.dynamic.add(g);registry.set(v.id,g);ready(v.kind).then(template=>{if(registry.get(v.id)!==g)return;g.add(template.clone(true));const lamp=new T.SpotLight('#ffe4b4',0,55,.38,.6,1.4);lamp.position.set(0,1.3,-2.5);const aim=new T.Object3D();aim.position.set(0,.5,-30);g.add(lamp,aim);lamp.target=aim;g.userData.headlight=lamp;g.userData.ready=true;}).catch(e=>{g.userData.error=e.message;});}}
const oldBlocked=P.blocked;
P.blocked=function(x,z,y,state){for(const v of state.vehicles||[]){if(v.id===state.riding)continue;const dx=x-v.x,dz=z-v.z,lx=dx*Math.cos(v.yaw)-dz*Math.sin(v.yaw),lz=dx*Math.sin(v.yaw)+dz*Math.cos(v.yaw);if(y<v.y+2.5&&y+1.7>v.y+.4&&Math.abs(lx)<(v.kind==='car'?1.4:1)&&Math.abs(lz)<(v.kind==='car'?2.8:3.5))return true;}return oldBlocked.call(this,x,z,y,state);};
function placement(world,state,p,kind){if((state.vehicles||[]).length>=64)return'乗り物の設置数が上限です';if(W.inCave(p.x,p.z,p.y)||SurvivalDungeons.at(p.x,p.z,p.y))return'乗り物は地上の広い場所で組み立ててください';const c=config[kind];for(let x=-c.width;x<=c.width+.01;x+=c.width)for(let z=-c.length;z<=c.length+.01;z+=c.length){const sample=probe({...p,yaw:state.yaw},x,z),h=W.ground(sample.x,sample.z);if(h<W.water+.5||Math.abs(h-p.y)>(kind==='car'?.7:.45)||world.blocked(sample.x,sample.z,h,state))return kind==='car'?'木や岩のない平らな場所（幅3m・長さ6m）を選んでください':'翼まで置ける平地（幅11m・長さ8m）が必要です';}if(state.jobs.some(j=>config[j.type]&&Math.hypot(j.x-p.x,j.z-p.z)<c.radius+config[j.type].radius+1))return'ほかの乗り物の組み立て場所から離してください';if(state.structures.some(s=>Math.hypot(s.x-p.x,s.z-p.z)<c.radius+4)||state.vehicles?.some(v=>Math.hypot(v.x-p.x,v.z-p.z)<c.radius+config[v.kind].radius+1))return'建物やほかの乗り物から離してください';return null;}
function create(state,job,world){state.vehicles||=[];const v={id:'v'+state.nextId++,kind:job.type,x:job.x,y:job.y,z:job.z,yaw:job.yaw??state.yaw,pitch:0,roll:0,speed:0,throttle:0,fuel:0,hp:100,airborne:false};state.vehicles.push(v);if(world&&Math.hypot(state.x-v.x,state.z-v.z)<config[v.kind].radius+1){for(let n=0;n<12;n++){const a=n*Math.PI/6,x=v.x+Math.sin(a)*(config[v.kind].radius+2),z=v.z+Math.cos(a)*(config[v.kind].radius+2),y=world.floor(x,z,v.y,state);if(Math.abs(y-v.y)<2&&!world.blocked(x,z,y,state)){Object.assign(state,{x,y,z});break;}}}return v;}
function target(state){if(state.riding){const v=state.vehicles?.find(v=>v.id===state.riding);return v?{type:'vehicle',data:v,label:'停車して E で降りる'}:null;}return(state.vehicles||[]).map(v=>({v,d:Math.hypot(state.x-v.x,state.z-v.z)})).filter(({v,d})=>d<(v.kind==='car'?4.4:5)&&Math.abs(state.y-v.y)<4).sort((a,b)=>a.d-b.d).map(({v})=>({type:'vehicle',data:v,label:config[v.kind].name,detail:'乗る・給油・修理'}))[0]||null;}
function mount(state,v){if(v.hp<=0)return'故障しています。鉄鉱石と樹脂で修理してください';if(!registry.get(v.id)?.userData.ready)return registry.get(v.id)?.userData.error||'車体モデルを読み込んでいます。少し待ってから乗ってください';state.riding=v.id;state.yaw=v.yaw;state.pitch=0;return null;}
function leave(world,state){const v=state.vehicles?.find(v=>v.id===state.riding);if(!v){state.riding=null;return null;}if(v.airborne||Math.abs(v.speed)>.8)return'地上で完全に停止してから降りてください';const c=config[v.kind];for(const a of[Math.PI/2,-Math.PI/2,Math.PI,0]){const x=v.x+Math.sin(v.yaw+a)*(c.width+1.6),z=v.z+Math.cos(v.yaw+a)*(c.width+1.6),y=world.floor(x,z,v.y,state);if(Math.abs(y-v.y)<2&&!world.blocked(x,z,y,state)){state.riding=null;Object.assign(state,{x,y,z});v.throttle=0;return null;}}return'降りる場所がふさがっています。少し移動してください';}
function refuel(state,v){if(v.airborne||Math.abs(v.speed)>.8)return'停止してから給油してください';if(v.fuel>=100)return'燃料は満タンです';if(!D.pay(state.inventory,{motorfuel:1}))return'車両用燃料が必要です';v.fuel=Math.min(100,v.fuel+25);return null;}
function repair(state,v){if(v.airborne||Math.abs(v.speed)>.8)return'停止してから修理してください';if(v.hp>=100)return'修理の必要はありません';if(!D.pay(state.inventory,{ore:4,resin:2}))return'修理には鉄鉱石4個と樹脂2個が必要です';v.hp=Math.min(100,v.hp+35);return null;}
function probe(v,lx,lz){return{x:v.x+Math.cos(v.yaw)*lx+Math.sin(v.yaw)*lz,z:v.z-Math.sin(v.yaw)*lx+Math.cos(v.yaw)*lz};}
function collision(world,state,v,x,z,y,air){const c=config[v.kind],at={...v,x,z};for(const [lx,lz,h]of [[0,0,.3],[-Math.min(c.width,1.05),-c.length,.4],[Math.min(c.width,1.05),-c.length,.4],[-Math.min(c.width,1.05),c.length,.4],[Math.min(c.width,1.05),c.length,.4],...(v.kind==='airplane'?[[-4.8,0,2.5],[4.8,0,2.5]]:[])]){const p=probe(at,lx,lz);if(Math.abs(p.x)>99990||Math.abs(p.z)>99990||world.blocked(p.x,p.z,y+h,state))return true;if((air||v.kind==='airplane')&&world.floor(p.x,p.z,y+h,state)>y+h+.15)return true;}return false;}
function step(world,state,camera,keys,dt,hurt=()=>{},toast=()=>{}){const v=state.vehicles?.find(v=>v.id===state.riding);if(!v){state.riding=null;return null;}const c=config[v.kind],steps=Math.max(1,Math.ceil(Math.max(1,Math.abs(v.speed))*dt/.3)),sub=dt/steps;let crashed=false;
 for(let n=0;n<steps;n++){const wasAirborne=v.airborne,oldSpeed=v.speed,oldYaw=v.yaw,powered=v.fuel>0&&v.hp>0;if(v.kind==='car'){const pedal=(keys.KeyW?1:0)-(keys.KeyS?1:0);const desired=powered?(pedal>0?26:pedal<0?-7:0):0;const accel=keys.Space?20:pedal?7:3;v.speed=T.MathUtils.moveTowards?T.MathUtils.moveTowards(v.speed,keys.Space?0:desired,accel*sub):v.speed+Math.sign((keys.Space?0:desired)-v.speed)*Math.min(Math.abs((keys.Space?0:desired)-v.speed),accel*sub);v.yaw+=((keys.KeyA?1:0)-(keys.KeyD?1:0))*v.speed*.035*sub;}
 else{v.throttle=T.MathUtils.clamp(v.throttle+((keys.KeyW?.45:0)-(keys.KeyS?.7:0))*sub,0,1);if(!powered)v.throttle=0;if(!v.airborne&&keys.KeyB)v.throttle=0;const desired=!v.airborne&&keys.KeyB?0:!v.airborne&&keys.KeyS&&v.throttle===0&&v.speed<1&&powered?-3:v.throttle*52;v.speed+=T.MathUtils.clamp(desired-v.speed,-(v.airborne?3:keys.KeyB?20:keys.KeyS?14:5)*sub,6*sub);v.speed=Math.max(v.airborne?0:-3,v.speed);const steer=(keys.KeyA?1:0)-(keys.KeyD?1:0);v.yaw+=steer*sub*(v.airborne?.6:Math.min(1,v.speed*.04));v.roll=T.MathUtils.lerp(v.roll,steer*(v.airborne?.28:0),Math.min(1,sub*3));if(!v.airborne&&keys.Space&&v.speed>=18){v.airborne=true;v.pitch=.12;v.y+=.12;}if(v.airborne){const pitch=(keys.Space?1:0)-(keys.KeyC||keys.ControlLeft||keys.ControlRight?1:0);v.pitch=T.MathUtils.clamp(v.pitch+(pitch?pitch*.38:-v.pitch*.55)*sub,-.32,.38);}}
 state.yaw+=v.yaw-oldYaw;const x=v.x-Math.sin(v.yaw)*v.speed*sub,z=v.z-Math.cos(v.yaw)*v.speed*sub,ground=world.floor(x,z,v.y,state);let y=v.y;
 if(v.kind==='car'){const rise=ground-v.y;if(ground<W.water+.2||Math.abs(rise)>.28+Math.abs(v.speed)*sub*.65){v.speed=0;continue;}y=ground;}
 else if(v.airborne){const sink=Math.max(0,18-v.speed)*.65+(powered?0:1.4);const vy=Math.sin(v.pitch)*v.speed-sink;y=Math.min(1800,v.y+vy*sub);if(y<=ground){if(v.speed>35||vy< -5){v.hp=Math.max(0,v.hp-Math.max(15,Math.abs(vy)*6+(v.speed-30)*2));hurt(18,true);if(state.riding!==v.id)return null;toast('強い着地で機体が傷みました');}y=ground;v.airborne=false;v.pitch=0;v.roll=0;v.speed=Math.min(v.speed,18);if(ground<W.water){v.hp=0;v.speed=0;toast('着水してエンジンが故障しました');}}}
 else{if(ground<W.water+.2||Math.abs(ground-v.y)>.18+v.speed*sub*.3){v.speed=0;continue;}y=ground;}
 if(collision(world,state,v,x,z,y,v.airborne)){v.speed=0;v.throttle=0;if(Math.abs(oldSpeed)>4&&!crashed){v.hp=Math.max(0,v.hp-Math.abs(oldSpeed)*1.2);hurt(Math.min(30,Math.abs(oldSpeed)*.6),true);if(state.riding!==v.id)return null;toast('衝突しました。停止して機体・車体を確認してください');crashed=true;}if(v.kind==='airplane'&&wasAirborne){const below=world.floor(v.x,v.z,v.y,state);v.y=Math.max(below,Math.min(v.y,y));if(v.y<=below+.02){v.airborne=false;v.pitch=0;v.roll=0;}}continue;}v.x=x;v.z=z;v.y=y;
 if(powered&&(Math.abs(v.speed)>.2||v.throttle>.05))v.fuel=Math.max(0,v.fuel-c.burn*sub*(v.kind==='car'?.4+.6*Math.abs(v.speed)/26:.35+.65*v.throttle));
 if(v.kind==='car'){const front=probe(v,0,-1.5),back=probe(v,0,1.5),left=probe(v,-.9,0),right=probe(v,.9,0);v.pitch=T.MathUtils.lerp(v.pitch,Math.atan2(world.floor(front.x,front.z,y,state)-world.floor(back.x,back.z,y,state),3),Math.min(1,sub*5));v.roll=T.MathUtils.lerp(v.roll,Math.atan2(world.floor(right.x,right.z,y,state)-world.floor(left.x,left.z,y,state),1.8),Math.min(1,sub*5));}}
 if(state.riding!==v.id)return null;state.x=v.x;state.z=v.z;state.y=v.y+1;state.stamina=Math.min(100,state.stamina+dt*10);const dist=v.kind==='car'?8:14,eyeY=v.y+(v.kind==='car'?4:6)-T.MathUtils.clamp(state.pitch,-.7,.7)*4;camera.position.set(v.x+Math.sin(state.yaw)*dist,Math.max(world.floor(v.x+Math.sin(state.yaw)*dist,v.z+Math.cos(state.yaw)*dist,eyeY,state)+1,eyeY),v.z+Math.cos(state.yaw)*dist);camera.lookAt(v.x,v.y+1.5,v.z);return{moving:false,running:false,riding:true};}
let hud,engine;
function update(world,state,dt,playing,paused,sound){sync(world,state);for(const v of state.vehicles||[]){const g=registry.get(v.id);if(!g)continue;g.visible=Math.hypot(state.x-v.x,state.z-v.z)<300;g.position.set(v.x,v.y,v.z);g.rotation.set(v.pitch,v.yaw,v.roll,'YXZ');if(g.userData.headlight){const hour=(state.worldTime||0)/720*24;g.userData.headlight.intensity=state.riding===v.id&&v.fuel>0&&(hour<7||hour>18)?3:0;}if(!paused){g.traverse(o=>{if(o.name.startsWith('wheel'))o.rotation.x-=v.speed*dt/(v.kind==='car'?.55:.42);if(o.name==='prop'&&v.fuel>0&&v.hp>0&&state.riding===v.id)o.rotation.z+=dt*(18+v.throttle*80);});}}const v=state.vehicles?.find(v=>v.id===state.riding);if(!hud){hud=document.createElement('div');hud.id='vehicleHud';document.body.append(hud);}hud.hidden=!playing||!v;document.body.classList.toggle('vehicleRiding',playing&&!!v);if(v)hud.innerHTML=`<strong>${config[v.kind].name}</strong><span>${Math.round(Math.abs(v.speed)*3.6)} km/h　燃料 ${Math.ceil(v.fuel)}%　耐久 ${Math.ceil(v.hp)}%${v.kind==='airplane'?'　出力 '+Math.round(v.throttle*100)+'%':''}</span><small>${v.kind==='car'?'W/S：前進・後退　A/D：ハンドル　Space：ブレーキ':'W/S：出力・減速　A/D：旋回　Space/C：機首上下　地上B：ブレーキ'}<br>R：停車して給油　E：停止して降りる</small>`;
 if(sound.context&&!engine){const ctx=sound.context,osc=ctx.createOscillator(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();osc.type='sawtooth';filter.type='lowpass';filter.frequency.value=220;gain.gain.value=0;osc.connect(filter);filter.connect(gain);gain.connect(sound.master);osc.start();engine={osc,gain,ctx};}if(engine){engine.gain.gain.setTargetAtTime(v&&!paused&&!sound.muted&&v.fuel>0&&v.hp>0?.018:0,engine.ctx.currentTime,.08);engine.osc.frequency.setTargetAtTime(v?(v.kind==='car'?35+Math.abs(v.speed)*2:65+v.throttle*75):35,engine.ctx.currentTime,.1);}}
window.SurvivalVehicles={config,ready,models,registry,sync,placement,create,target,mount,leave,refuel,repair,step,update};
})();
